=Analiza la siguiente instrucción de refinamiento del usuario y determina qué campos del travel_brief deben actualizarse y qué pasos del planificador deben volver a ejecutarse.

INSTRUCCIÓN DEL USUARIO:
{{ $json.feedback_text }}

SESSION STATE ACTUAL:
{{ JSON.stringify($json.current_session) }}

PLAN ACTUAL:
{{ JSON.stringify($json.current_plan) }}

parameters.jsCode:
// Parsear output del agente de refinamiento
const agentOutput = $input.first().json.output || $input.first().json.text || '';
const currentSession = $('Cargar Sesión').first().json.current_session;
const sessionId = $('Cargar Sesión').first().json.session_id;
const staticData = $getWorkflowStaticData('global');

let refinedState;
let cleaned = agentOutput.trim();
if (cleaned.startsWith('```json')) cleaned = cleaned.replace(/^```json\s*/, '').trim();
if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```\s*/, '').trim();
if (cleaned.endsWith('```')) cleaned = cleaned.replace(/\s*```$/, '').trim();

try {
  refinedState = JSON.parse(cleaned);
} catch(e) {
  // Si falla el parse, ejecutar todo con el brief actual sin cambios
  refinedState = {
    ...currentSession,
    revision_count: (currentSession.revision_count || 0) + 1,
    status: 'awaiting_search',
    steps_to_run: 'all',
    feedback_instruction: 'Instrucción no interpretada — re-ejecutando plan completo'
  };
}

// Asegurar campos obligatorios
refinedState.session_id = sessionId;
refinedState.status = 'awaiting_search';
if (!refinedState.steps_to_run) refinedState.steps_to_run = 'all';

// FIX v25.3: preservar el plan original — el Agente de Refinamiento no lo gestiona
// ni lo incluye en su contrato de output. Sin esto, el plan existente se pierde
// y steps_to_run parciales (ej. 'hotels') no tienen nada que conservar.
refinedState.plan = currentSession.plan || null;

// Guardar estado actualizado
staticData[sessionId] = refinedState;

return [{ json: {
  session_id: sessionId,
  session_state: refinedState,
  route: 'refinamiento'
} }];

// Preparar session_state para el motor planificador
// Unifica ambas rutas (formulario inicial y refinamiento)
const input = $input.first().json;

const sessionState = input.session_state;
const tb = sessionState.travel_brief || {};
const revisionCount = sessionState.revision_count || 0;
const stepsToRun = sessionState.steps_to_run || 'all';

// Construir segmentos
const destinations = tb.destination_city || [];
const segments = [];

if (destinations.length === 1) {
  segments.push({
    segment_index: 0,
    origin: tb.origin_city,
    destination: destinations[0],
    departure_date: tb.departure_date,
    return_date: tb.return_date
  });
} else {
  segments.push({
    segment_index: 0,
    origin: tb.origin_city,
    destination: destinations[0],
    departure_date: tb.departure_date,
    return_date: null
  });
  for (let i = 1; i < destinations.length; i++) {
    segments.push({
      segment_index: i,
      origin: destinations[i - 1],
      destination: destinations[i],
      departure_date: null,
      return_date: i === destinations.length - 1 ? tb.return_date : null
    });
  }
}

return [{ json: {
  session_state: sessionState,
  travel_brief: tb,
  revision_count: revisionCount,
  steps_to_run: stepsToRun,
  segments: segments,
  unique_destinations: [...new Set(destinations)],
  existing_plan: sessionState.plan || null,
  feedback_instruction: sessionState.feedback_instruction || null
} }];

parameters.text:
=Ejecuta la secuencia de planificación de viaje para el estado de sesión siguiente. Sigue TODAS las instrucciones del system prompt EXACTAMENTE. Devuelve ÚNICAMENTE un objeto JSON válido — sin texto, sin markdown, sin bloques de código.

ESTADO DE SESIÓN:
{{ JSON.stringify($json.session_state) }}

SEGMENTOS A PROCESAR:
{{ JSON.stringify($json.segments) }}

DESTINOS ÚNICOS PARA TAVILY:
{{ JSON.stringify($json.unique_destinations) }}

PASOS A EJECUTAR: {{ $json.steps_to_run }}

CONTEO DE REVISIÓN: {{ $json.revision_count }}

INSTRUCCIÓN DE REFINAMIENTO (si aplica): {{ $json.feedback_instruction || 'ninguna — ejecución inicial completa' }}

PLAN EXISTENTE (si aplica — usar como base para refinamientos parciales):
{{ JSON.stringify($json.existing_plan) }}

parameters.jsCode:
const agentOutput = $input.first().json.output || $input.first().json.text || '';
const prepInput = $('Preparar Motor Planificador').first().json;
const sessionId = prepInput.session_state.session_id;
const revisionCount = prepInput.revision_count;
const staticData = $getWorkflowStaticData('global');

// Limpiar markdown si el LLM lo añadió
let cleaned = agentOutput.trim();
if (cleaned.startsWith('```json')) cleaned = cleaned.replace(/^```json\s*/, '').trim();
if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```\s*/, '').trim();
if (cleaned.endsWith('```')) cleaned = cleaned.replace(/\s*```$/, '').trim();

let result;
try {
  result = JSON.parse(cleaned);
} catch(e) {
  return [{ json: {
    status: 'error',
    session_id: sessionId,
    revision_count: revisionCount,
    error_detail: `Output no-JSON del motor planificador: ${e.message}. Raw (primeros 300 chars): ${agentOutput.substring(0, 300)}`,
    warnings: [],
    plan: null
  } }];
}

// ── SIEMPRE sobrescribir generated_at — no confiar en el agente ──
result.generated_at = new Date().toISOString();

// ── Safety net c): stars debe ser null si hotel_class no es válido ──
if (result.plan && result.plan.segments) {
  result.plan.segments.forEach(seg => {
    if (seg.hotel && (seg.hotel.stars === 0 || seg.hotel.stars === undefined || seg.hotel.stars === '')) {
      seg.hotel.stars = null;
    }
  });
}

// ── Safety net g): booking_url de vuelos — SIEMPRE reconstruir con formato
// travel/flights?q= (verificado con una petición real: HTTP 200, precarga la
// ruta y fecha correctas). Se probó un flujo de booking_token + booking_options
// de SerpAPI para dar la URL de reserva real del proveedor, pero SerpAPI
// devuelve la MISMA url generica "travel/clk/f" para todos los proveedores —
// sin datos adicionales que no expone la API, esa url da 404. Se descartó ese
// flujo por no funcionar; este enlace de búsqueda es el que sí funciona. ──
if (result.plan && result.plan.segments) {
  result.plan.segments.forEach(seg => {
    const ob = seg.flights?.outbound;
    const rt = seg.flights?.return;
    if (ob && ob.origin && ob.destination && ob.departure_datetime) {
      const date = ob.departure_datetime.substring(0, 10);
      ob.booking_url = `https://www.google.com/travel/flights?q=Flights%20to%20${ob.destination}%20from%20${ob.origin}%20on%20${date}`;
    }
    if (rt && rt.origin && rt.destination && rt.departure_datetime) {
      const date2 = rt.departure_datetime.substring(0, 10);
      rt.booking_url = `https://www.google.com/travel/flights?q=Flights%20to%20${rt.destination}%20from%20${rt.origin}%20on%20${date2}`;
    }
  });
}

// ── Safety net plan_notes: mínimo 1 nota si el agente las omitió ──
// GPT-4.1 puede omitir plan_notes aunque Tavily haya respondido.
// Este safety net construye notas mínimas desde el contexto del plan.
if (result.plan && (!result.plan.plan_notes || result.plan.plan_notes.length === 0)) {
  const seg = result.plan.segments?.[0];
  const dest = seg?.destination || 'el destino';
  const origin = seg?.origin || 'tu ciudad';
  const checkIn = seg?.hotel?.check_in || '';
  const month = checkIn ? new Date(checkIn).toLocaleString('es-ES', { month: 'long' }) : 'verano';
  result.plan.plan_notes = [
    `Visa: Verificar requisitos de entrada para ciudadanos de ${origin} en ${dest}.`,
    `Clima: Consultar previsión meteorológica para ${dest} en ${month}.`,
    `Transporte local: Se recomienda usar metro y/o taxi para desplazarse por ${dest}.`
  ];
}

// ── Safety net f): trip_summary mínimo si el agente lo omitió ──
if (result.plan && (!result.plan.trip_summary || result.plan.trip_summary.trim() === '')) {
  const seg = result.plan.segments?.[0];
  if (seg) {
    const dest = seg.destination || 'tu destino';
    const days = result.plan.daily_itinerary?.length || 0;
    result.plan.trip_summary = `Un viaje de ${days} días a ${dest} con vuelo y alojamiento confirmados.`;
  }
}

// ── Extracción de coste de transporte desde plan_notes (safety net) ──
if (result.plan && result.plan.cost_summary &&
    (result.plan.cost_summary.estimated_local_transport_usd === null ||
     result.plan.cost_summary.estimated_local_transport_usd === 0)) {
  const notes = (result.plan.plan_notes || []).join(' ');
  const patterns = [
    /(\d+[,.]?\d*)\s*[€$£](?:[^.]{0,20})?(?:metro|taxi|bus|tren|aeropuerto|transfer|tarjeta|pase)/i,
    /(?:metro|taxi|bus|tren|aeropuerto|transfer|tarjeta|pase)[^.]{0,30}?(\d+[,.]?\d*)\s*[€$£]/i,
    /(?:metro|taxi|transport)[^.]{0,30}?(\d+(?:[.,]\d+)?)\s*(?:euros?|usd|dollars?)/i
  ];
  for (const pattern of patterns) {
    const match = notes.match(pattern);
    if (match) {
      const val = parseFloat((match[1] || match[2] || '0').replace(',', '.'));
      if (val > 0 && val < 300) {
        result.plan.cost_summary.estimated_local_transport_usd = val;
        result.plan.cost_summary.local_transport_data_source = 'tavily';
        const cs = result.plan.cost_summary;
        cs.total_usd = (cs.flights_usd||0)+(cs.hotel_usd||0)+(cs.activities_usd||0)+val+(cs.inter_city_transport_usd||0);
        cs.budget_remaining_usd = (cs.budget_total_usd||0) - cs.total_usd;
        break;
      }
    }
  }
}

// ── Seguridad: verificar presupuesto de forma determinista. El agente a veces
// no se autovalida bien la aritmética y devuelve plan_ready aunque el total
// supere el presupuesto — aquí se recalcula con código, no con el LLM. ──
if (result.plan && result.plan.cost_summary) {
  const cs = result.plan.cost_summary;
  const total = (cs.flights_usd || 0) + (cs.hotel_usd || 0) + (cs.activities_usd || 0) +
                (cs.inter_city_transport_usd || 0) + (cs.estimated_local_transport_usd || 0);
  const budget = cs.budget_total_usd || 0;
  if (budget > 0 && total > budget) {
    const amountOver = Math.round((total - budget) * 100) / 100;
    result.warnings = result.warnings || [];
    const already = result.warnings.find(w => w.type === 'budget_exceeded');
    if (already) {
      already.requires_user_approval = true;
      already.amount_over = amountOver;
    } else {
      result.warnings.push({
        type: 'budget_exceeded',
        detail: `El coste total (${total.toFixed(2)} USD) supera el presupuesto solicitado (${budget.toFixed(2)} USD) en ${amountOver.toFixed(2)} USD.`,
        proposed_change: 'Sube el presupuesto, reduce noches, pide alojamiento mas economico o cambia de destino.',
        requires_user_approval: true,
        amount_over: amountOver
      });
    }
  }
}

// ── Seguridad: no puede ser plan_ready si hay warnings críticas ──
const hasCritical = (result.warnings || []).some(w => w.requires_user_approval === true);
if (result.status === 'plan_ready' && hasCritical) result.status = 'needs_user_input';

// ── Safety net: daily_itinerary vacío → generar estructura mínima desde activities ──
if (result.plan && (!result.plan.daily_itinerary || result.plan.daily_itinerary.length === 0)) {
  const seg = result.plan.segments?.[0];
  if (seg) {
    const arrivalDate = (seg.flights?.outbound?.arrival_datetime || '').substring(0, 10);
    const returnDate  = (seg.flights?.return?.departure_datetime || '').substring(0, 10);
    const dest = seg.destination || '';
    if (arrivalDate && returnDate) {
      const start = new Date(arrivalDate);
      const end   = new Date(returnDate);
      const days  = [];
      const activities = seg.activities || [];
      // Indexar actividades por fecha
      const actByDate = {};
      activities.forEach(a => { if (a.date) { if (!actByDate[a.date]) actByDate[a.date] = []; actByDate[a.date].push(a); } });
      let d = new Date(start);
      let dayNum = 1;
      while (d <= end) {
        const dateStr = d.toISOString().substring(0, 10);
        const dayActs = (actByDate[dateStr] || []).map(a => ({
          time: a.start_time || '10:00',
          name: a.name,
          duration_hours: a.duration_hours || 3,
          price_usd: a.price_usd || 0,
          booking_url: a.booking_url || ''
        }));
        let title, summary;
        if (dateStr === arrivalDate) {
          title = `Día de llegada a ${dest}`;
          summary = `Llegada a ${dest}. Check-in en el hotel. Tarde libre para explorar el barrio.`;
        } else if (dateStr === returnDate) {
          title = `Último día en ${dest} — Regreso`;
          summary = `Check-out del hotel. Vuelo de regreso. Mañana libre para últimas compras o paseo.`;
        } else if (dayActs.length > 0) {
          title = dayActs.map(a => a.name).join(' · ');
          summary = `Día dedicado a: ${dayActs.map(a => a.name).join(', ')}.`;
        } else {
          title = `Día libre para caminar y conocer ${dest}`;
          summary = `Día libre para explorar ${dest} a tu ritmo, descubrir mercados locales, cafés y calles del barrio.`;
        }
        days.push({ day: dayNum, date: dateStr, title, summary, activities: dayActs });
        d.setDate(d.getDate() + 1);
        dayNum++;
      }
      result.plan.daily_itinerary = days;
    }
  }
}

result.session_id = result.session_id || sessionId;
result.revision_count = result.revision_count ?? revisionCount;

// Persistir en static data
const currentSession = staticData[sessionId] || {};
staticData[sessionId] = {
  ...currentSession,
  status: result.status,
  plan: result.plan,
  warnings: result.warnings || [],
  revision_count: result.revision_count,
  generated_at: result.generated_at
};

return [{ json: result }];

const result = $input.first().json;

// Capturar token usage del Motor Planificador
// n8n expone el tokenUsage en el contexto del nodo agente
let tokenUsage = null;
try {
  const agentNode = $('Motor Planificador — Agent 2').first();
  tokenUsage = agentNode.json?.tokenUsage
    || agentNode.json?.usage
    || agentNode.json?.llmOutput?.tokenUsage
    || null;
} catch(e) {
  tokenUsage = null;
}

// Calcular tiempo de ejecución aproximado
const generatedAt = new Date(result.generated_at || Date.now());
const now = new Date();
const executionMs = now.getTime() - generatedAt.getTime();

// Contar elementos del plan para métricas
const segment = result.plan?.segments?.[0] || {};
const activitiesCount = segment.activities?.length || 0;
const itineraryDays = result.plan?.daily_itinerary?.length || 0;
const planNotesCount = result.plan?.plan_notes?.length || 0;
const warningsCount = result.warnings?.length || 0;

result._debug = {
  token_usage: tokenUsage,
  execution_time_ms: executionMs > 0 && executionMs < 300000 ? executionMs : null,
  plan_metrics: {
    activities_found: activitiesCount,
    itinerary_days: itineraryDays,
    plan_notes: planNotesCount,
    warnings: warningsCount,
    has_flights: !!(segment.flights?.outbound?.airline),
    has_hotel: !!(segment.hotel?.name),
    tools_called: result.steps_executed || 'all'
  }
};

return [{ json: result }];

// Preparar el payload para guardar en Supabase (tabla travel_plans)
// Solo procesa si el plan está listo (plan_ready)
const result = $input.first().json;

// Guardar solo planes completos — no needs_user_input ni error
if (result.status !== 'plan_ready') {
  // Pasar el resultado sin modificar y marcar que no se debe guardar
  return [{ json: { ...result, _skip_supabase: true } }];
}

const plan = result.plan || {};
const segment = plan.segments?.[0] || {};
const costSummary = plan.cost_summary || {};

// Recuperar el travel_brief del session_state para metadatos
let travelBrief = {};
try {
  const prepMotor = $('Preparar Motor Planificador').first().json;
  travelBrief = prepMotor.session_state?.travel_brief || {};
} catch(e) {
  travelBrief = {};
}

// Construir el registro para Supabase
const record = {
  session_id: result.session_id,
  status: result.status,
  destination: segment.destination || travelBrief.destination_city?.[0] || 'unknown',
  origin: segment.origin || travelBrief.origin_city || 'unknown',
  departure_date: segment.flights?.outbound?.departure_datetime?.slice(0,10)
    || travelBrief.departure_date || null,
  return_date: segment.flights?.return?.departure_datetime?.slice(0,10)
    || travelBrief.return_date || null,
  budget_usd: costSummary.budget_total_usd || travelBrief.budget_total_usd || null,
  total_cost_usd: costSummary.total_usd || null,
  travelers_count: (travelBrief.travelers?.adults || 0) + (travelBrief.travelers?.children?.length || 0),
  activity_interests: travelBrief.activity_interests || [],
  plan: plan
};

// Pasar tanto el registro para Supabase como el resultado original para el Responder
return [{ json: {
  ...result,
  _supabase_record: record,
  _skip_supabase: false
} }];

// Extraer solo el registro para Supabase (los campos de la tabla)
const record = $input.first().json._supabase_record;
if (!record) {
  return [{ json: { _no_record: true } }];
}
return [{ json: record }];

// Enriquecer daily_itinerary con UNA coordenada por día para el mapa del frontend.
// Prioridad: (1) gps de actividad concreta ese día → (2) geocoding del POI vía OpenStreetMap → (3) centro de la ciudad.
const result = $input.first().json;
const plan = result.plan;

if (!plan || !Array.isArray(plan.daily_itinerary)) {
  return [{ json: result }];
}

// Centro de ciudad como fallback (ya lo tenemos en el travel_brief)
let cityCenter = null;
try {
  const prep = $('Preparar Motor Planificador').first().json;
  const ll = prep.session_state?.travel_brief?.destination_city_ll; // formato @lat,lng,15z
  if (ll) {
    const parts = ll.replace('@', '').split(',');
    cityCenter = { lat: parseFloat(parts[0]), lng: parseFloat(parts[1]) };
  }
} catch (e) {}

const city = plan.segments?.[0]?.destination || '';

// Índice de actividades con coordenadas por fecha
const actByDate = {};
(plan.segments?.[0]?.activities || []).forEach(a => {
  if (a.date && a.lat != null && a.lng != null) {
    actByDate[a.date] = { lat: a.lat, lng: a.lng };
  }
});

// Geocoding vía Nominatim (OpenStreetMap) — sin API key
async function geocode(name) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://nominatim.openstreetmap.org/search',
      qs: { q: `${name}, ${city}`, format: 'json', limit: 1 },
      headers: { 'User-Agent': 'TFM-TravelPlanner/1.0 (educational project)' },
      json: true
    });
    if (Array.isArray(res) && res.length > 0) {
      return { lat: parseFloat(res[0].lat), lng: parseFloat(res[0].lon) };
    }
  } catch (e) {}
  return null;
}

for (const day of plan.daily_itinerary) {
  let coord = null;
  let source = 'none';

  // 1. Coordenada de una actividad concreta ese día
  if (actByDate[day.date]) {
    coord = actByDate[day.date];
    source = 'activity';
  }
  // 2. Geocoding del punto de interés mencionado
  else if (Array.isArray(day.points_of_interest) && day.points_of_interest.length > 0) {
    const poi = typeof day.points_of_interest[0] === 'string'
      ? day.points_of_interest[0]
      : day.points_of_interest[0]?.name;
    if (poi) {
      coord = await geocode.call(this, poi);
      if (coord) source = 'geocoded';
      // Nominatim: máx 1 petición/seg — respetar el límite
      await new Promise(r => setTimeout(r, 1100));
    }
  }
  // 3. Fallback: centro de la ciudad
  if (!coord && cityCenter) {
    coord = cityCenter;
    source = 'city_center';
  }

  if (coord) {
    day.lat = coord.lat;
    day.lng = coord.lng;
  } else {
    day.lat = null;
    day.lng = null;
  }
  day.coordinate_source = source;
}

return [{ json: result }];
